const searchSupportTickets = `-- name: SearchSupportTickets :many

SELECT
  t.id, t.user_id, t.status, t.created_at, t.updated_at, t.subject, t.priority, t.last_message_at, t.customer_unread_count, t.closed_at, t.queue_id, t.assignee_id, t.assigned_at, t.first_response_at, t.resolved_at, t.reopened_count, t.operator_unread_count, t.merged_into_ticket_id,
  q.code AS queue_code,
  q.first_response_target_seconds,
  q.resolution_target_seconds,
  COALESCE(a.display_name, '') AS assignee_name,
  u.status AS customer_status,
  (q.first_response_target_seconds > 0
    AND t.first_response_at IS NULL
    AND t.created_at < now() - make_interval(secs => q.first_response_target_seconds))
    AS first_response_breached,
  (SELECT count(*)::bigint FROM support_messages m WHERE m.ticket_id = t.id) AS message_count,
  ARRAY(
    SELECT g.code FROM support_ticket_tags tt
    JOIN support_tags g ON g.id = tt.tag_id
    WHERE tt.ticket_id = t.id
    ORDER BY g.code
  )::text[] AS tags
FROM support_tickets t
JOIN support_queues q ON q.id = t.queue_id
JOIN users u ON u.id = t.user_id
LEFT JOIN admin_users a ON a.id = t.assignee_id
WHERE ($1::uuid IS NULL OR t.queue_id = $1::uuid)
  AND ($2::text IS NULL OR t.status = $2::text)
  AND ($3::text IS NULL OR t.priority = $3::text)
  AND ($4::uuid IS NULL OR t.assignee_id = $4::uuid)
  AND (NOT $5::boolean OR t.assignee_id IS NULL)
  AND ($6::uuid IS NULL OR t.user_id = $6::uuid)
  AND ($7::text IS NULL OR EXISTS (
    SELECT 1 FROM support_ticket_tags tt
    JOIN support_tags g ON g.id = tt.tag_id
    WHERE tt.ticket_id = t.id AND g.code = $7::text
  ))
  AND (
    $8::timestamptz IS NULL
    OR (t.last_message_at, t.id) > ($8::timestamptz, $9::uuid)
  )
ORDER BY t.last_message_at, t.id
LIMIT $10
`

