const setSupportTicketStatus = `-- name: SetSupportTicketStatus :one
UPDATE support_tickets
SET status = $1,
    resolved_at = CASE
      WHEN $1::text IN ('resolved', 'closed') THEN COALESCE(resolved_at, now())
      ELSE NULL
    END,
    closed_at = CASE WHEN $1::text = 'closed' THEN now() ELSE NULL END,
    reopened_count = CASE
      WHEN $1::text IN ('open', 'pending') AND resolved_at IS NOT NULL
        THEN reopened_count + 1
      ELSE reopened_count
    END,
    updated_at = now()
WHERE id = $2 AND status <> 'merged'
RETURNING id, user_id, status, created_at, updated_at, subject, priority, last_message_at, customer_unread_count, closed_at, queue_id, assignee_id, assigned_at, first_response_at, resolved_at, reopened_count, operator_unread_count, merged_into_ticket_id
`

type SetSupportTicketStatusParams struct {
	Status   string      `json:"status"`
	TicketID pgtype.UUID `json:"ticket_id"`
}

// Resolution and reopening are recorded rather than inferred.
//
// `resolved_at` is set the first time a ticket reaches a terminal state and
// cleared when it comes back, and `reopened_count` counts the round trips —
// which is the signal that an answer did not actually answer the question.
func (q *Queries) SetSupportTicketStatus(ctx context.Context, arg SetSupportTicketStatusParams) (SupportTicket, error) {
	row := q.db.QueryRow(ctx, setSupportTicketStatus, arg.Status, arg.TicketID)
	var i SupportTicket
	err := row.Scan(
		&i.ID,
		&i.UserID,
		&i.Status,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.Subject,
		&i.Priority,
		&i.LastMessageAt,
		&i.CustomerUnreadCount,
		&i.ClosedAt,
		&i.QueueID,
		&i.AssigneeID,
		&i.AssignedAt,
		&i.FirstResponseAt,
		&i.ResolvedAt,
		&i.ReopenedCount,
		&i.OperatorUnreadCount,
		&i.MergedIntoTicketID,
	)
	return i, err
}

const supportDeskSummary = `-- name: SupportDeskSummary :one
SELECT
  (SELECT count(*)::bigint FROM support_tickets WHERE status IN ('open', 'pending')) AS open_tickets,
  (SELECT count(*)::bigint FROM support_tickets
    WHERE status IN ('open', 'pending') AND assignee_id IS NULL) AS unassigned_tickets,
  (SELECT count(*)::bigint FROM support_tickets t
    JOIN support_queues q ON q.id = t.queue_id
    WHERE t.status IN ('open', 'pending')
      AND q.first_response_target_seconds > 0
      AND t.first_response_at IS NULL
      AND t.created_at < now() - make_interval(secs => q.first_response_target_seconds))
    AS breached_tickets,
  (SELECT count(*)::bigint FROM support_tickets t
    WHERE t.resolved_at >= $1) AS resolved_in_window,
  COALESCE((
    SELECT percentile_cont(0.5) WITHIN GROUP (
      ORDER BY extract(epoch FROM (t.first_response_at - t.created_at))
    )
    FROM support_tickets t
    WHERE t.first_response_at IS NOT NULL AND t.first_response_at >= $1
  ), 0)::bigint AS median_first_response_seconds
`

type SupportDeskSummaryRow struct {
	OpenTickets                int64 `json:"open_tickets"`
	UnassignedTickets          int64 `json:"unassigned_tickets"`
	BreachedTickets            int64 `json:"breached_tickets"`
	ResolvedInWindow           int64 `json:"resolved_in_window"`
	MedianFirstResponseSeconds int64 `json:"median_first_response_seconds"`
}

// The desk at a glance: what is waiting, what is overdue, and how quickly the
// desk is answering.
func (q *Queries) SupportDeskSummary(ctx context.Context, since pgtype.Timestamptz) (SupportDeskSummaryRow, error) {
	row := q.db.QueryRow(ctx, supportDeskSummary, since)
	var i SupportDeskSummaryRow
	err := row.Scan(
		&i.OpenTickets,
		&i.UnassignedTickets,
		&i.BreachedTickets,
		&i.ResolvedInWindow,
		&i.MedianFirstResponseSeconds,
	)
	return i, err
}

const supportWorkloadReport = `-- name: SupportWorkloadReport :many

SELECT
  a.id AS operator_id,
  a.display_name,
  (SELECT count(*)::bigint FROM support_messages m
    WHERE m.author_id = a.id AND m.created_at >= $1) AS replies,
  (SELECT count(*)::bigint FROM support_tickets t
    WHERE t.assignee_id = a.id AND t.status IN ('open', 'pending')) AS open_tickets,
  (SELECT count(*)::bigint FROM support_tickets t
    WHERE t.assignee_id = a.id AND t.resolved_at >= $1) AS resolved_tickets,
  COALESCE((
    SELECT percentile_cont(0.5) WITHIN GROUP (
      ORDER BY extract(epoch FROM (t.first_response_at - t.created_at))
    )
    FROM support_tickets t
    WHERE t.assignee_id = a.id
      AND t.first_response_at IS NOT NULL
      AND t.first_response_at >= $1
  ), 0)::bigint AS median_first_response_seconds
FROM admin_users a
WHERE a.status = 'active'
ORDER BY a.display_name
`

type SupportWorkloadReportRow struct {
	OperatorID                 pgtype.UUID `json:"operator_id"`
	DisplayName                string      `json:"display_name"`
	Replies                    int64       `json:"replies"`
	OpenTickets                int64       `json:"open_tickets"`
	ResolvedTickets            int64       `json:"resolved_tickets"`
	MedianFirstResponseSeconds int64       `json:"median_first_response_seconds"`
}

// ---------------------------------------------------------------------------
// Workload and response-time reporting
// ---------------------------------------------------------------------------
// Per-operator workload over a window.
//
// The definitions are deliberately narrow and are documented beside the report:
// `replies` counts operator messages the operator actually wrote, `resolved`
// counts tickets that reached a terminal state while assigned to them, and the
// response measure is the median rather than the mean, because one ticket
// answered a week late would otherwise make a good week look bad.
func (q *Queries) SupportWorkloadReport(ctx context.Context, since pgtype.Timestamptz) ([]SupportWorkloadReportRow, error) {
	rows, err := q.db.Query(ctx, supportWorkloadReport, since)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SupportWorkloadReportRow{}
	for rows.Next() {
		var i SupportWorkloadReportRow
		if err := rows.Scan(
			&i.OperatorID,
			&i.DisplayName,
			&i.Replies,
			&i.OpenTickets,
			&i.ResolvedTickets,
			&i.MedianFirstResponseSeconds,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

