func (q *Queries) UpsertSupportTag(ctx context.Context, arg UpsertSupportTagParams) (SupportTag, error) {
	row := q.db.QueryRow(ctx, upsertSupportTag, arg.Code, arg.NameEn, arg.NameRu)
	var i SupportTag
	err := row.Scan(
		&i.ID,
		&i.Code,
		&i.NameEn,
		&i.NameRu,
		&i.ArchivedAt,
		&i.CreatedAt,
	)
	return i, err
}
